public boolean shouldPrintMessage(int timestamp, String message) {
    // Initialize a HashMap to store the last printed timestamp for each message
    // Static because it needs to persist between method calls
    static Map<String, Integer> messageTimestampMap = new HashMap<>();

    // Check if the message is already in the map
    if (messageTimestampMap.containsKey(message)) {
        // Retrieve the last printed timestamp for the message
        int lastPrintedTimestamp = messageTimestampMap.get(message);
        // Check if the time difference is less than 10 seconds
        if (timestamp - lastPrintedTimestamp < 10) {
            // Return false as the message should not be printed yet
            return false;
        }
    }
    // Update the map with the new timestamp for the message
    messageTimestampMap.put(message, timestamp);
    // Return true as the message should be printed
    return true;
}

