    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    if (tour.isEmpty()) {
        return graph.createPath();
    }

    Iterator<E> edgeIterator = tour.iterator();
    E firstEdge = edgeIterator.next();
    V startVertex = graph.getEdgeSource(firstEdge);

    List<E> edges = new ArrayList<>();
    edges.add(firstEdge);

    while (edgeIterator.hasNext()) {
        E currentEdge = edgeIterator.next();
        V currentStart = graph.getEdgeSource(currentEdge);
        V currentEnd = graph.getEdgeTarget(currentEdge);

        if (!currentStart.equals(startVertex)) {
            edges.add(currentEdge);
            startVertex = currentEnd;
        }
    }

    return graph.createPath(edges);
}

