public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    // Handle the case where the relative path is absolute
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    // Split the path into components
    String[] pathComponents = path.split("/");
    String[] relativeComponents = relativePath.split("/");

    // Remove the last component of the path
    if (pathComponents.length > 1) {
        pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
    }

    // Apply the relative components to the path
    for (String component : relativeComponents) {
        if (component.equals("..")) {
            // Move up one directory
            if (pathComponents.length > 0) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else if (!component.isEmpty()) {
            // Add the component to the path
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            pathComponents[pathComponents.length - 1] = component;
        }
    }

    // Join the path components back into a single string
    return String.join("/", pathComponents);
}

