protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start >= end) {
        throw new IllegalArgumentException("Invalid time range: start must be less than end");
    }

    long maxDurationMillis = TimeUnit.SECONDS.toMillis(FETCH_DATA_DURATION);
    List<TimeRange> timeRanges = new ArrayList<>();

    for (long currentTime = start; currentTime < end; currentTime += maxDurationMillis) {
        long nextTime = Math.min(currentTime + maxDurationMillis, end);
        timeRanges.add(new TimeRange(currentTime, nextTime));
    }

    return timeRanges;
}

